'use client';
import Link from 'next/link';
import { useEffect, useState } from 'react';
import { Activity, ChevronDown, CircleUserRound, GitBranch, Menu, Network, Search, X } from 'lucide-react';
import { apiClient, type AuthUser } from '@/lib/api-client';

export function SiteNav() { const [open, setOpen] = useState(false); const [user, setUser] = useState<AuthUser | null>(null); useEffect(() => { void apiClient.auth.me().then((result) => { if (result.success && result.data) setUser(result.data); }); }, []); return <nav className="site-nav"><Link href="/" className="brand"><span className="brand-mark"><GitBranch size={16} /></span><span>version<span>flow</span></span></Link><div className={`nav-links ${open ? 'nav-open' : ''}`}><a href="#product" onClick={() => setOpen(false)}>Product</a><a href="#features" onClick={() => setOpen(false)}>Features</a><a href="#how-it-works" onClick={() => setOpen(false)}>How it works</a><a href="#faqs" onClick={() => setOpen(false)}>FAQs</a>{user ? <Link href="/dashboard" aria-label={`Open dashboard for ${user.name}`} className="signed-in-user" onClick={() => setOpen(false)}><CircleUserRound size={20} /><span className="signed-in-label">Signed in</span></Link> : <Link href="/auth/login" onClick={() => setOpen(false)}>Sign in</Link>}</div><button className="icon-button nav-menu" aria-label={open ? 'Close navigation' : 'Open navigation'} onClick={() => setOpen(!open)}>{open ? <X size={20} /> : <Menu size={20} />}</button></nav>; }

export function FlowDiagram() { return <div className="flow-visual" aria-label="Illustration of API changes propagating through dependencies"><div className="flow-topline"><span>LIVE ECOSYSTEM MAP</span><span className="mono">v0.4.2 → v0.4.3</span></div><div className="flow-canvas"><div className="flow-lines"><i /><i /><i /><i /></div><div className="flow-node node-api"><span className="node-icon orange"><GitBranch size={17} /></span><small>API</small><strong>Orders API</strong><em>v0.4.3</em></div><div className="flow-node node-diff"><span className="node-icon"><Activity size={17} /></span><small>CHANGE</small><strong>2 breaking</strong><em>1 warning</em></div><div className="flow-node node-one"><span className="node-icon"><Network size={17} /></span><small>DEPENDENCY</small><strong>Checkout</strong><em>consumer</em></div><div className="flow-node node-two"><span className="node-icon"><Network size={17} /></span><small>DEPENDENCY</small><strong>Fulfillment</strong><em>consumer</em></div><div className="flow-node node-three"><span className="node-icon"><Network size={17} /></span><small>DEPENDENCY</small><strong>Partner API</strong><em>external</em></div></div><div className="flow-bottom"><span><b className="orange-text">●</b> Propagation detected</span><span>Impact score <b>72</b></span></div></div> }

export function ProductPreview() { return <div className="product-preview"><div className="preview-sidebar"><span className="preview-logo">vf</span><span className="preview-active">⌂</span><span>⌁</span><span>◌</span><span>◫</span><span>⚙</span></div><div className="preview-main"><div className="preview-top"><div><small>OVERVIEW</small><h3>Good morning, team.</h3></div><div className="preview-search"><Search size={13} /> Search</div></div><div className="preview-metrics"><div><small>TOTAL APIS</small><b>24</b><em>+3 this month</em></div><div><small>VERSIONS</small><b>67</b><em>+12 this month</em></div><div><small>DEPENDENCIES</small><b>142</b><em>+8 this month</em></div></div><div className="preview-content"><div className="preview-panel"><small>RECENT CHANGES</small><div className="mini-row"><span className="mini-dot red" /><b>Orders API</b><span>v0.4.3</span><em>2 breaking</em></div><div className="mini-row"><span className="mini-dot amber" /><b>Identity API</b><span>v2.1.0</span><em>1 warning</em></div><div className="mini-row"><span className="mini-dot green" /><b>Billing API</b><span>v1.8.2</span><em>compatible</em></div></div><div className="preview-panel graph-panel"><small>DEPENDENCY SIGNAL</small><div className="mini-graph"><i /><i /><i /><i /><i /><i /></div><strong>18 APIs connected</strong></div></div></div></div> }

const faqs = [['What is VersionFlow?', 'VersionFlow is a developer-first intelligence layer for understanding how APIs evolve and how those changes move through an ecosystem.'], ['Which formats are supported?', 'The MVP is focused on importing XML API specifications. More formats can be added as the product evolves.'], ['Does it detect dependencies automatically?', 'Not in this foundation release. Dependency visualization is illustrative while the underlying detection capability is being built.'], ['How does VersionFlow handle versioning?', 'It gives teams a place to organize versions and see changes between them. Version comparison and lifecycle automation are not implemented yet.'], ['Can it identify breaking changes?', 'The dashboard uses illustrative demo data only. Production change analysis is not active in this phase.'], ['Do I need to connect a repository?', 'No. Repository integrations are intentionally out of scope for the MVP foundation.'], ['How is pricing structured?', 'Pricing has not been announced. This preview is focused on communicating the product direction.']];
export function Faqs() { const [active, setActive] = useState<number | null>(0); return <section className="faq-section" id="faqs"><div className="section-kicker">Questions, answered</div><div className="faq-layout"><h2>Good to<br /><span>know.</span></h2><div className="faq-list">{faqs.map(([q, a], i) => <div className={`faq-item ${active === i ? 'faq-active' : ''}`} key={q}><button onClick={() => setActive(active === i ? null : i)} aria-expanded={active === i}><span>{q}</span><ChevronDown size={17} /></button>{active === i && <p>{a}</p>}</div>)}</div></div></section> }

export function SiteFooter() { return <footer className="site-footer"><div className="footer-brand"><Link href="/" className="brand"><span className="brand-mark"><GitBranch size={16} /></span><span>version<span>flow</span></span></Link><p>Change APIs with confidence.</p></div><div className="footer-links"><div><b>Product</b><a href="#features">Features</a><a href="#preview">Platform</a><Link href="/dashboard">Dashboard</Link></div><div><b>Resources</b><a href="#how-it-works">How it works</a><a href="#faqs">FAQs</a><a href="#product">MVP scope</a></div><div><b>Company</b><a href="mailto:hello@versionflow.dev">Contact</a></div></div><div className="footer-bottom"><span>© 2026 VersionFlow. Built for teams who ship.</span><span>Developer-first by design.</span></div></footer> }
